examples.template:
Row(horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    filters.forEach { filter ->
        Box {
            MonarchButton(text = filter, onClick = { open = filter }, size = MonarchButtonSize.Sm)
            MonarchPopover(
                expanded = open == filter,
                onDismissRequest = { open = null },
                label = {{title}},
            ) {
                MonarchText(text = {{title}}, style = MonarchTextStyle.Subheading, heading = true)
                MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2, Alignment.End),
                ) {
                    MonarchButton(
                        text = "Cancel",
                        onClick = { open = null },
                        variant = MonarchButtonVariant.Secondary,
                        size = MonarchButtonSize.Sm,
                    )
                    MonarchButton(
                        text = {{confirmLabel}},
                        onClick = {
                            filters = filters - filter
                            open = null
                        },
                        variant = MonarchButtonVariant.Danger,
                        size = MonarchButtonSize.Sm,
                    )
                }
            }
        }
    }
}

